"use client";
import React, { useEffect, useState } from 'react';
import InventoryModal from './InventoryModal';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';

export default function InventoryList() {
  const [items, setItems] = useState<any[]>([]);
  const [q, setQ] = useState('');
  const [sort, setSort] = useState<'name' | 'qty'>('name');

  const fetchItems = async () => {
    try {
      const res = await fetch('/api/inventory');
      const data = await res.json();
      setItems(Array.isArray(data) ? data : []);
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => { fetchItems(); }, []);

  const filtered = items
    .filter(i => !q || (i.itemName || '').toLowerCase().includes(q.toLowerCase()) || (i.category || '').toLowerCase().includes(q.toLowerCase()))
    .sort((a,b) => sort === 'name' ? String(a.itemName).localeCompare(String(b.itemName)) : (Number(b.quantityAvailable) - Number(a.quantityAvailable)));

  return (
    <div>
      <div className="flex justify-between items-center mb-4">
        <div className="flex gap-3">
          <Input placeholder="Search inventory" value={q} onChange={(e:any) => setQ(e.target.value)} />
          <Button onClick={() => setSort(s => s === 'name' ? 'qty' : 'name')}>Sort: {sort}</Button>
        </div>
        <InventoryModal onSaved={fetchItems} />
      </div>

      <div className="grid gap-3">
        {filtered.map(it => (
          <div key={it._id || it.id} className="p-4 border-2 border-black flex justify-between items-center">
            <div>
              <div className="font-bold">{it.itemName}</div>
              <div className="text-sm text-muted-foreground">{it.category} — {it.unit}</div>
              <div className="text-sm">{it.description}</div>
            </div>
            <div className="text-right">
              <div className={`font-bold ${it.quantityAvailable <= 0 ? 'text-red-600' : it.quantityAvailable < 5 ? 'text-yellow-600' : 'text-green-600'}`}>{it.quantityAvailable} {it.unit}</div>
              <div className="text-sm">Status: {it.status}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
